<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller;use App\Models\{User,Role};use App\Services\CredentialService;use Illuminate\Http\Request;use Illuminate\Support\Facades\DB;
class CredentialController extends Controller{
private function view(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('credentials.view'),403);}
private function generateOk(Request $r){abort_unless($r->user()->isSuperAdmin()||$r->user()->canDo('credentials.generate'),403);}
public function index(Request $r,CredentialService $c){$this->view($r);$groups=DB::table('study_groups')->where('active',1)->orderBy('name')->get();$q=User::with('roles')->orderBy('name');if($r->filled('group'))$q->whereIn('student_id',DB::table('students')->where('current_group_id',$r->integer('group'))->pluck('id'));$users=$q->paginate(50)->withQueryString();foreach($users as $u)$u->plain_password=$c->reveal($u->password_encrypted);return view('admin.credentials.index',compact('users','groups'));}
public function generate(Request $r,CredentialService $c){$this->generateOk($r);$d=$r->validate(['group_id'=>'required|exists:study_groups,id','regenerate'=>'nullable|boolean']);$role=Role::where('code','student')->firstOrFail();$students=DB::table('students')->where('current_group_id',$d['group_id'])->where('status','active')->orderBy('last_name')->orderBy('first_name')->get();$count=0;foreach($students as $s){$u=User::where('student_id',$s->id)->first();if($u&&!$r->boolean('regenerate')&&$u->password_encrypted)continue;$login=$u?($u->login?:$c->login($s->last_name,$s->first_name,$s->id)):$c->login($s->last_name,$s->first_name,$s->id);$plain=$c->password();$data=$c->pack($plain)+['name'=>trim($s->last_name.' '.$s->first_name.' '.$s->middle_name),'login'=>$login,'email'=>($u&&$u->email)?$u->email:$login.'@students.local','student_id'=>$s->id,'is_active'=>true];if($u)$u->update($data);else $u=User::create($data);$u->roles()->syncWithoutDetaching([$role->id]);$count++;}return redirect()->route('admin.credentials.index',['group'=>$d['group_id']])->with('success','Создано/обновлено учётных записей: '.$count);}
public function reveal(Request $r,User $user,CredentialService $c){$this->view($r);return response()->json(['login'=>$user->login?:$user->email,'password'=>$c->reveal($user->password_encrypted)]);}
public function print(Request $r,CredentialService $c){$this->view($r);$gid=$r->validate(['group'=>'required|exists:study_groups,id'])['group'];$group=DB::table('study_groups')->find($gid);$users=User::whereIn('student_id',DB::table('students')->where('current_group_id',$gid)->pluck('id'))->orderBy('name')->get();foreach($users as $u)$u->plain_password=$c->reveal($u->password_encrypted);return view('admin.credentials.print',compact('group','users'));}
}